<?= $this->extend('layouts/app') ?><?= $this->section('content') ?>
<?php $query=http_build_query(['type'=>$type]+$filters); ?>
<div class="page-head"><div><h1><?= esc($event['name']??'Reports') ?></h1><p><?= esc($reportLabel) ?></p></div><div class="page-actions"><a class="btn" target="_blank" href="<?= site_url('reports/print').'?'.$query ?>"><?= ui_icon('printer') ?><span>Print</span></a><a class="btn primary" href="<?= site_url('reports/xlsx').'?'.$query ?>"><?= ui_icon('save') ?><span>Excel Export</span></a></div></div>
<section class="panel report-panel"><div class="panel-head report-head"><form method="get" class="toolbar report-toolbar"><label>Event<select name="event_id"><?php $active=array_values(array_filter($events,static fn($e)=>(int)($e['is_active']??0)===1));$other=array_values(array_filter($events,static fn($e)=>(int)($e['is_active']??0)!==1)); ?><?php if($active): ?><optgroup label="Active"><?php foreach($active as $e): ?><option value="<?= (int)$e['id'] ?>" <?= (int)$filters['event_id']===(int)$e['id']?'selected':'' ?>><?= esc($e['name'].' · '.$e['year'].' (Active)') ?></option><?php endforeach; ?></optgroup><?php endif; ?><?php if($other): ?><optgroup label="Other Events"><?php foreach($other as $e): ?><option value="<?= (int)$e['id'] ?>" <?= (int)$filters['event_id']===(int)$e['id']?'selected':'' ?>><?= esc($e['name'].' · '.$e['year']) ?></option><?php endforeach; ?></optgroup><?php endif; ?></select></label><label>Report Type<select name="type"><?php foreach(['standings'=>'Team Standings','medal_tally'=>'Medal Tally','sport_results'=>'Sport Results Summary','sport_rankings'=>'Per-Sport Rankings','validation_log'=>'Validation Log','full_event'=>'Full Event Report'] as $k=>$v): ?><option value="<?= $k ?>" <?= $type===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select></label><label>Sport<select name="sport_id"><option value="">All Sports</option><?php foreach($sports as $sport): ?><option value="<?= (int)$sport['id'] ?>" <?= (int)$filters['sport_id']===(int)$sport['id']?'selected':'' ?>><?= esc($sport['name'].' · '.$sport['category']) ?></option><?php endforeach; ?></select></label><label>Category<select name="category"><option value="">All Categories</option><?php foreach($categories as $category): ?><option value="<?= esc($category,'attr') ?>" <?= $filters['category']===$category?'selected':'' ?>><?= esc($category) ?></option><?php endforeach; ?></select></label><label>Result Status<select name="status"><option value="">All Statuses</option><option value="validated" <?= $filters['status']==='validated'?'selected':'' ?>>Validated (Official)</option><option value="pending" <?= $filters['status']==='pending'?'selected':'' ?>>Pending (Unofficial)</option></select></label><label>Date Range<select name="date_range"><option value="all_event" <?= $filters['date_range']==='all_event'?'selected':'' ?>>All Event</option><option value="today" <?= $filters['date_range']==='today'?'selected':'' ?>>Today</option><option value="this_week" <?= $filters['date_range']==='this_week'?'selected':'' ?>>This Week</option><option value="custom" <?= $filters['date_range']==='custom'?'selected':'' ?>>Custom</option></select></label><label>Start<input type="date" name="from" value="<?= esc($filters['from'],'attr') ?>"></label><label>End<input type="date" name="to" value="<?= esc($filters['to'],'attr') ?>"></label><button class="btn primary" type="submit"><?= ui_icon('filter') ?><span>Apply</span></button></form></div><p class="report-filter-summary"><?= esc($filterSummary) ?></p><div class="table-wrap" role="region" aria-label="Report results table" tabindex="0"><table><?php if($columns): ?><thead><tr><?php foreach($columns as $col): ?><th class="<?= in_array($col,$numericCols,true)?'number':'' ?>"><?= esc($columnLabels[$col]??$col) ?></th><?php endforeach; ?></tr></thead><?php endif; ?><tbody><?php foreach($rows as $row): ?><tr><?php foreach($columns as $col): ?><?php $value=$row[$col]??null;$display=in_array($col,$pointCols,true)&&$value!==null&&$value!==''?format_points($value):($value===null||$value===''?'—':(string)$value); ?><td class="<?= in_array($col,$numericCols,true)?'number':'' ?>"><?= esc($display) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(empty($rows)): ?><tr><td colspan="<?= max(1,count($columns)) ?>"><div class="empty">No report data matches the selected filters.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?= $this->endSection() ?>
